  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "Diclofenac has an absolute oral bioavailability of 54% in humans after oral administration, directly exceeding the 20% threshold and supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Suvorexant has a mean absolute oral bioavailability of 82% in humans under fasted conditions, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Brotizolam has an absolute oral bioavailability of 70% in young subjects, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Indomethacin has an absolute oral bioavailability of 85% in adults, supporting high F despite age/formulation-dependent lower values in infants.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Alfuzosin has an absolute oral bioavailability of 49% in humans under fed conditions, above the threshold and supportive of high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C60"],
      "claim": "Iclepertin has an absolute oral bioavailability of 72% in humans for a 25 mg tablet under fasted conditions, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Etoposide has a mean absolute oral bioavailability of 57% with a median of 47%, supporting high F despite interpatient variability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Lumiracoxib has an absolute oral bioavailability of 74.0 ± 8.6% in healthy subjects, directly supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability values well above 20% in humans, with values ranging from roughly 49% to 85%. The query molecule is a small, lipophilic, oral drug-like compound with no evidence pointing to poor absorption or extensive first-pass loss. Therefore, high oral bioavailability at the F ≥ 20% threshold is strongly supported.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement is available for the query molecule itself.",
    "Query-specific solubility, permeability, and first-pass metabolism data are not directly reported.",
    "Potential formulation-dependent or food-dependent effects on the query molecule are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

